#!/usr/bin/env bash
set -euo pipefail
cd /workspaces/FOX-OPTIMISER
python3 - <<'PYINSTALL'
from pathlib import Path
pages=[Path("index.html"),Path("preview-v2.html")]
if any(not p.is_file() or "</body>" not in p.read_text() for p in pages): raise SystemExit("STOP: HTML entry files missing or unexpected.")
Path("fox-forecast-v23.js").write_text('/* Synthetic forecast-error research only; no hardware or network access. */\n(function(){\n\'use strict\';\nfunction run(mode,solarFactor,loadFactor){\n const capacity=10.24,eff=.95,min=capacity*.05,target=capacity*.20;\n const clocks=Array.from({length:36},(_,i)=>5.5+i*.5);\n const solar=clocks.map(t=>Math.max(0,Math.sin((t-7)/11*Math.PI))*(t<18?.32:0));\n const prices=clocks.map(t=>t>=16&&t<19?35:8);\n let energy=capacity,scale=1,loadScale=1,at19=null,revenue=0,grid=0,cancelled=0,residual=0;\n function plan(start,e,pv,home){\n  const actions=Array(36).fill(0),order=clocks.map((_,i)=>i).filter(i=>i>=start&&clocks[i]<19).sort((a,b)=>prices[b]-prices[a]||a-b);\n  function replay(a){let x=e,checkpoint=null;for(let j=start;j<36;j++){const z=step(x,pv[j],home[j],a[j]);x=z.end;if(clocks[j]===18.5)checkpoint=x;}return checkpoint===null||checkpoint>=target-1e-8;}\n  for(const i of order){for(let q=0;q<18;q++){actions[i]+=.1;if(!replay(actions)){actions[i]-=.1;break;}}}\n  return actions;\n }\n function step(e,pv,h,request){\n  const solarHome=Math.min(pv,h),deficit=h-solarHome,surplus=pv-solarHome;\n  const batteryHome=Math.min(deficit,2.5*eff,Math.max(0,(e-min)*eff));\n  const afterHome=e-batteryHome/eff;\n  const charge=Math.min(surplus,2.5,Math.max(0,(capacity-afterHome)/eff));\n  const natural=Math.min(1.75,surplus-charge),curtail=surplus-charge-natural;\n  const forced=charge>1e-9?0:Math.min(request,1.75-natural,Math.max(0,(2.5-batteryHome/eff)*eff),Math.max(0,(afterHome-min)*eff));\n  return {end:afterHome+charge*eff-forced/eff,batteryHome,charge,natural,curtail,forced,grid:deficit-batteryHome,solarHome};\n }\n const initial=plan(0,energy,solar,clocks.map(()=>.15));\n for(let i=0;i<36;i++){\n  // A sudden noon change is only discovered from the completed previous interval.\n  const actualPV=solar[i]*(clocks[i]>=12?solarFactor:1),actualHome=.15*(clocks[i]>=12?loadFactor:1);\n  const remaining=mode===\'adaptive\'?plan(i,energy,solar.map(x=>x*scale),clocks.map(()=>.15*loadScale)):initial;\n  const z=step(energy,actualPV,actualHome,remaining[i]);\n  cancelled+=Math.max(0,initial[i]-remaining[i]);\n  residual=Math.max(residual,Math.abs(energy+z.charge*eff-(z.batteryHome+z.forced)/eff-z.end),Math.abs(actualPV-z.solarHome-z.charge-z.natural-z.curtail));\n  energy=z.end;revenue+=(z.forced+z.natural)*prices[i]/100;grid+=z.grid;\n  if(clocks[i]===18.5)at19=energy/capacity*100;\n  if(solar[i]>.001)scale=actualPV/solar[i];loadScale=actualHome/.15;\n }\n return {at19,end:energy,revenue,grid,cancelled,residual,pass:at19>=20-1e-7};\n}\nif(typeof module!==\'undefined\')module.exports={run};\nif(typeof document===\'undefined\')return;\nconst section=document.createElement(\'section\');section.style.cssText=\'padding:20px;margin:20px 0;border:1px solid #52718c;border-radius:16px;background:#101d30;color:#e5edf7\';\nsection.innerHTML=\'<h3>Forecast errors & replanning · v2.3</h3><p>SYNTHETIC RESEARCH ONLY. A fixed hypothetical price curve and solar profile, not historical results or live readings. At noon, solar or household use changes unexpectedly. Adaptive mode updates forecasts from completed half-hours only; it cannot see future actual data. Target: 20% at 19:00, no extra SOC buffer. No hardware commands.</p><button type="button">Run forecast-error comparisons</button><div aria-live="polite"></div><p>Half-hour energy simulation: 3.5 kW net export and 5 kW battery limits apply within each modelled slot; instantaneous physical enforcement is not tested. Financial comparisons, wear and overnight charging are outside this test.</p>\';\n(document.querySelector(\'main\')||document.body).append(section);\nsection.querySelector(\'button\').onclick=()=>{\n const out=section.querySelector(\'[aria-live]\');out.replaceChildren();\n for(const [name,pv,h] of [[\'Forecast matches\',1,1],[\'Solar falls 50% at noon\',.5,1],[\'Home demand doubles at noon\',1,2],[\'Both changes at noon\',.5,2]]){\n  const a=run(\'fixed\',pv,h),b=run(\'adaptive\',pv,h),p=document.createElement(\'p\');\n  p.textContent=name+\': fixed 19:00 SOC \'+a.at19.toFixed(2)+\'% (\'+(a.pass?\'PASS\':\'MISS\')+\'); adaptive \'+b.at19.toFixed(2)+\'% (\'+(b.pass?\'PASS\':\'MISS\')+\'). Adaptive grid use \'+b.grid.toFixed(2)+\' kWh; cancelled/reduced planned export \'+b.cancelled.toFixed(2)+\' kWh. Energy residual \'+b.residual.toFixed(8)+\' kWh.\';out.append(p);\n }\n};\n})();\n')
Path("fox-forecast-v23-selftest.js").write_text("const assert=require('node:assert/strict'),{run}=require('./fox-forecast-v23.js');\nfor(const pv of [0,.5,1])for(const load of [1,2,5])for(const mode of ['fixed','adaptive']){const r=run(mode,pv,load);assert(Number.isFinite(r.at19));assert(r.end>=.512-1e-8);assert(r.residual<1e-8);}\nfor(const [pv,h] of [[1,1],[.5,1],[1,2],[.5,2]])assert(run('adaptive',pv,h).pass);\nassert(!run('fixed',.5,2).pass);\nconsole.log('V2.3 PASS: physical energy accounting, minimum SOC, reserve misses reported and adaptive synthetic scenarios');\n")
for p in pages:
 s=p.read_text()
 if "fox-forecast-v23.js" not in s: p.write_text(s.replace("</body>", '<script src="fox-forecast-v23.js?v=230"></script>\n</body>'))
PYINSTALL
node --check fox-forecast-v23.js
node fox-forecast-v23-selftest.js
echo "v2.3 synthetic research panel installed. No hardware control."
